package com.wygtv.tv;

import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;import org.json.*;import java.net.*;import java.io.*;import java.util.*;import androidx.media3.common.MediaItem;import androidx.media3.exoplayer.ExoPlayer;import androidx.media3.ui.PlayerView;

public class MainActivity extends Activity {
 final int BG=0xff080F24, PANEL=0xff172B4D, BLUE=0xff4CB6FF; LinearLayout root,body,side,detail; TextView status; String mode="home", category="", name=""; JSONArray categories=new JSONArray(),items=new JSONArray(); ExoPlayer player; android.content.SharedPreferences prefs;
 int dp(int n){return (int)(getResources().getDisplayMetrics().density*n+.5f);} String saved(String k){return prefs.getString(k,"");}
 @Override public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("wygtv",MODE_PRIVATE);getWindow().getDecorView().setSystemUiVisibility(5894|1024|512);home();}
 GradientDrawable bg(int color){GradientDrawable g=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{color,0xff0A1934});g.setCornerRadius(dp(15));g.setStroke(dp(1),0xff42658B);return g;}
 TextView label(String t,int size){TextView v=new TextView(this);v.setText(t);v.setTextColor(-1);v.setTextSize(size);v.setGravity(Gravity.CENTER_VERTICAL);return v;}
 TextView button(String text,LinearLayout parent,Runnable r){TextView v=label(text,21);v.setFocusable(true);v.setPadding(dp(18),dp(13),dp(12),dp(13));v.setBackground(bg(PANEL));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(dp(5),dp(5),dp(5),dp(5));parent.addView(v,lp);v.setOnClickListener(w->r.run());v.setOnFocusChangeListener((w,f)->{v.setBackground(bg(f?0xff23639B:PANEL));v.setScaleX(f?1.025f:1f);v.setScaleY(f?1.025f:1f);});return v;}
 void shell(String title){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(24),dp(14),dp(24),dp(12));root.setBackgroundColor(BG);setContentView(root);TextView h=label("✦ WygTV     "+title,30);h.setTypeface(null,Typeface.BOLD);h.setTextColor(BLUE);root.addView(h,new LinearLayout.LayoutParams(-1,dp(65)));body=new LinearLayout(this);root.addView(body,new LinearLayout.LayoutParams(-1,0,1));status=label("",13);status.setTextColor(0xffA8C9E8);root.addView(status,new LinearLayout.LayoutParams(-1,dp(30)));updateStatus();}
 void updateStatus(){String s=saved("host");status.setText(s.isEmpty()?"No playlist connected":"Playlist: "+saved("title")+"  •  "+s+"  •  "+saved("expiry"));}
 void home(){mode="home";shell("SPACE • HOME");LinearLayout center=new LinearLayout(this);center.setOrientation(LinearLayout.VERTICAL);center.setPadding(dp(90),dp(18),dp(90),0);body.addView(center,new LinearLayout.LayoutParams(-1,-1));TextView intro=label("WELCOME TO WygTV  ✦  SELECT A DESTINATION",24);intro.setGravity(Gravity.CENTER);center.addView(intro,new LinearLayout.LayoutParams(-1,dp(80)));button("⚙  Manage / Login to Playlist",center,()->login());button("▣  Live TV",center,()->browse("live"));button("▶  Movies",center,()->browse("vod"));button("▤  Series",center,()->browse("series"));button("★  Favorites",center,()->favorites());}
 void login(){mode="login";shell("MANAGE PLAYLISTS");ScrollView scroll=new ScrollView(this);body.addView(scroll);LinearLayout form=new LinearLayout(this);form.setPadding(dp(100),dp(10),dp(100),0);form.setOrientation(LinearLayout.VERTICAL);scroll.addView(form);EditText title=field(form,"Playlist name",saved("title"));EditText host=field(form,"Server URL (http://host:port)",saved("host"));EditText user=field(form,"Username",saved("user"));EditText pass=field(form,"Password",saved("pass"));pass.setInputType(129);button("Save & Connect",form,()->{String h=host.getText().toString().trim().replaceAll("/+$","");prefs.edit().putString("title",title.getText().toString()).putString("host",h).putString("user",user.getText().toString()).putString("pass",pass.getText().toString()).apply();request("player_api.php",data->{JSONObject info=data.optJSONObject("user_info");if(info!=null){prefs.edit().putString("expiry",info.optString("exp_date","Unknown")).apply();}home();},"Connection failed");});button("Return to Home",form,()->home());}
 EditText field(LinearLayout parent,String hint,String val){EditText e=new EditText(this);e.setSingleLine(true);e.setHint(hint);e.setText(val);e.setTextColor(-1);e.setHintTextColor(0xffAABBD2);parent.addView(e,new LinearLayout.LayoutParams(-1,dp(57)));return e;}
 String base(){return saved("host")+"/player_api.php?username="+enc(saved("user"))+"&password="+enc(saved("pass"));}String enc(String s){try{return java.net.URLEncoder.encode(s,"UTF-8");}catch(Exception e){return s;}}
 interface Done{void run(JSONObject obj);} void request(String action,Done cb,String error){if(saved("host").isEmpty()){new AlertDialog.Builder(this).setMessage("Add a playlist first").setPositiveButton("Login",(d,w)->login()).setNegativeButton("Cancel",null).show();return;}new Thread(()->{try{String url=action.equals("player_api.php")?base():base()+"&action="+action;HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(12000);c.setReadTimeout(16000);try(InputStream in=c.getInputStream()){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);String text=out.toString("UTF-8");JSONObject obj=text.trim().startsWith("[")?new JSONObject().put("list",new JSONArray(text)):new JSONObject(text);runOnUiThread(()->cb.run(obj));}finally{c.disconnect();}}catch(Exception e){runOnUiThread(()->new AlertDialog.Builder(this).setMessage(error+": "+e.getMessage()).setPositiveButton("OK",null).show());}}).start();}
 void browse(String m){mode=m;category="";shell(m.equals("live")?"LIVE TV":m.equals("vod")?"MOVIES":"SERIES");side=new LinearLayout(this);side.setOrientation(LinearLayout.VERTICAL);body.addView(side,new LinearLayout.LayoutParams(0,-1,1));detail=new LinearLayout(this);detail.setOrientation(LinearLayout.VERTICAL);body.addView(detail,new LinearLayout.LayoutParams(0,-1,2));button("← Home",side,()->home());button("★ Favorites",side,()->favorites());request(m.equals("live")?"get_live_categories":m.equals("vod")?"get_vod_categories":"get_series_categories",o->{categories=o.optJSONArray("list");if(categories==null)categories=new JSONArray();showCategories();},"Unable to load categories");}
 void showCategories(){side.removeViews(2,Math.max(0,side.getChildCount()-2));button("All categories",side,()->loadItems(""));for(int i=0;i<categories.length();i++){JSONObject c=categories.optJSONObject(i);if(c==null)continue;String id=c.optString("category_id"),title=c.optString("category_name","Category");button("› "+title,side,()->loadItems(id));}loadItems("");}
 void loadItems(String id){category=id;String a=mode.equals("live")?"get_live_streams":mode.equals("vod")?"get_vod_streams":"get_series";request(a+(id.isEmpty()?"":"&category_id="+enc(id)),o->{items=o.optJSONArray("list");if(items==null)items=new JSONArray();showItems();},"Unable to load content");}
 void showItems(){detail.removeAllViews();button("← Categories",detail,()->{detail.removeAllViews();});ScrollView sv=new ScrollView(this);detail.addView(sv);LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);sv.addView(list);int limit=Math.min(items.length(),1000);for(int i=0;i<limit;i++){JSONObject item=items.optJSONObject(i);if(item==null)continue;String title=item.optString("name","Untitled");button(title,list,()->select(item));}}
 void select(JSONObject item){String title=item.optString("name","Untitled");String type=mode;String id=item.optString(type.equals("series")?"series_id":"stream_id");new AlertDialog.Builder(this).setTitle(title).setItems(new String[]{"Play / Open",isFavorite(type,id)?"Remove Favorite":"Add Favorite","Cancel"},(d,which)->{if(which==0){if(type.equals("series"))episodes(id,title);else play(type,id,item.optString("container_extension",type.equals("live")?"ts":"mp4"),title);}if(which==1){String key="fav_"+type+"_"+id;prefs.edit().putString(key,isFavorite(type,id)?"":title).apply();}}).show();}
 boolean isFavorite(String type,String id){return !saved("fav_"+type+"_"+id).isEmpty();}
 void favorites(){mode="favorites";shell("FAVORITES");LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);body.addView(list);button("← Home",list,()->home());for(Map.Entry<String,?> e:prefs.getAll().entrySet()){String k=e.getKey();if(!k.startsWith("fav_")||String.valueOf(e.getValue()).isEmpty())continue;String[] parts=k.split("_",3);if(parts.length!=3)continue;String t=parts[1],id=parts[2],title=String.valueOf(e.getValue());button("★ "+title,list,()->{if(t.equals("series"))episodes(id,title);else play(t,id,t.equals("live")?"ts":"mp4",title);});}}
 void episodes(String id,String title){mode="episodes";shell("SERIES • "+title);LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);ScrollView sv=new ScrollView(this);body.addView(sv);sv.addView(list);button("← Series",list,()->browse("series"));request("get_series_info&series_id="+enc(id),o->{JSONObject seasons=o.optJSONObject("episodes");if(seasons==null)return;Iterator<String> keys=seasons.keys();while(keys.hasNext()){String season=keys.next();button("Season "+season,list,()->{JSONArray ep=seasons.optJSONArray(season);if(ep==null)return;list.removeViews(1,list.getChildCount()-1);button("← Seasons",list,()->episodes(id,title));for(int i=0;i<ep.length();i++){JSONObject e=ep.optJSONObject(i);if(e==null)continue;String eid=e.optString("id"),ext=e.optString("container_extension","mp4"),et=e.optString("title","Episode "+(i+1));button(et,list,()->play("series",eid,ext,et));}});}},"Unable to load episodes");}
 void play(String type,String id,String ext,String title){String path=type.equals("live")?"live":type.equals("vod")?"movie":"series";String url=saved("host")+"/"+path+"/"+enc(saved("user"))+"/"+enc(saved("pass"))+"/"+id+"."+ext;mode="player";if(player!=null)player.release();player=new ExoPlayer.Builder(this).build();PlayerView view=new PlayerView(this);view.setPlayer(player);view.setUseController(true);setContentView(view);player.setMediaItem(MediaItem.fromUri(url));player.prepare();player.play();view.requestFocus();}
 @Override public void onBackPressed(){if(player!=null){player.release();player=null;home();return;}if(mode.equals("home")){super.onBackPressed();return;}home();}
 @Override protected void onDestroy(){if(player!=null){player.release();player=null;}super.onDestroy();}
}
